-- GENERATED by `wfj generate` from data/gossip/gossip-9d.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["9d027465ecfaf866"] = { "I coboldi stanno riconquistando la ⟦Coldtooth Mine=Miniera di Dentefreddo⟧!", "." },
  ["9d03621376d3a2ca"] = { "Come desideri...", "." },
  ["9d0626f0b9d29a0b"] = { "È un piacere rivederti, {name}. Il tuo aiuto ha dato una spinta notevole alla sicurezza delle nostre linee di rifornimento. Spero che tu capisca l'importanza della logistica in grandi sforzi bellici come questo.", "." },
  ["9d08f07568ee518c"] = { "E quello come lo chiami? Se quello è combattere, allora io sono Lothar in persona!", "." },
  ["9d0fc948731ec925"] = { "Guardi me, <bello/bella>?", "." },
  ["9d12021659ff54d8"] = { "Ecco! È tutto finito, {name}.", "." },
  ["9d25486cdba2a3d3"] = { "Uldaman è un'antica cripta dei Titani rimasta sepolta sotto terra dalla creazione del mondo. Gli scavi dei nani nella città hanno di recente liberato le prime creazioni fallite dei Titani: i trogg. Le leggende narrano che, quando i Titani giudicarono un fallimento l'esperimento dei trogg, ci riprovarono, e da lì nacque la razza dei nani. Questi segreti sono registrati sui leggendari Discs of Norgannon, enormi manufatti che giacciono nelle profondità dell'antica città, protetti da giganteschi costrutti di pietra vivente.", "." },
  ["9d2a3612d3186c53"] = { "Presto Lokholar sorgerà... Presto... Molto, molto presto...", "." },
  ["9d2adacd03d43c15"] = { "Voglio ascoltare il tuo racconto.", "." },
  ["9d2c57484092c789"] = { "Un tempo grande città degli elfi della notte, vi regnavano gli ⟦Highborne=Alti Nobili⟧, che praticavano magie arcane grandi e potenti. Ora sono maledetti e infestano quelle terre, e la loro città in rovina è caduta preda dei naga Spitelash. A quanto ne so, i naga frugano tra le rovine in cerca di potenti manufatti degli ⟦Highborne=Alti Nobili⟧.", "." },
  ["9d34a3c13518b6b4"] = { "Io sente puzza di vivi!", "." },
  ["9d3b29d679699ef1"] = { "Fatti sotto!", "." },
  ["9d3ea46fe561671d"] = { "Il ⟦Stormpike Graveyard=Cimitero dei Piccatonante⟧ è stato conquistato dall'⟦Horde=Orda⟧!", "." },
  ["9d3ffd35d2b66513"] = { "Puoi dirmi di più sulla situazione dell'⟦Zephras Isle=Isola di Zephras⟧ e dei Windshaper?", "." },
  ["9d483e0c650d9e7b"] = { "Sono qui per imparare, Daio.", "." },
  ["9d4a547634de8b4f"] = { "Alzatevi e difendete il vostro padrone!", "." },
  ["9d4d41e5c5556545"] = { "Via, a Orgrimmar, {name}!", "." },
  ["9d5538b3537614a3"] = { "Di solito lascio quel genere di cose agli gnomi. Se vuoi intraprendere questa professione, di sicuro troverai qualche gnomo a ⟦Stormwind=Roccavento⟧ disposto ad addestrarti.", "." },
  ["9d5651a4fe1ab2a1"] = { "Sveglia, soldato! L'intelligence dei Piccatonante riferisce che un maestro ingegnere goblin è stato fatto prigioniero dai troll Asciafredda. I cani dei Lupi Bianchi stanno cercando di liberarlo per usare i suoi congegni e distruggerci! Non permettere che accada.", "." },
  ["9d5a19784f40476d"] = { "Ho ancora le cicatrici di quella notte.", "." },
  ["9d5b0daf8b2b7a4f"] = { "Ciao. No, Marvon di sicuro non c'è, e non tornerà per un bel po'. A dire il vero, comincio a preoccuparmi un po' per lui...\n\nSpero che torni presto. È arrivato un grosso baule per lui ed è troppo pesante perché io riesca a trascinarlo dentro! Ho dovuto lasciarlo fuori, vicino alla porta...", "." },
  ["9d624378bc9fad21"] = { "Sei pronto a riportare la palla, bello?", "." },
  ["9d6285e654a699b2"] = { "Uccidete quel lurido {race}!", "." },
  ["9d6a4f43672db88a"] = { "Raccontami una storia, John.", "." },
  ["9d6fa6e0befb6685"] = { "Oh, hai ancora un mucchio di cose da imparare. Ti insegnerei tutto se potessi, ma sto ancora imparando anch'io! Perché non parli con Trixie Quickswitch a ⟦Ironforge=Forgiardente⟧? Ti aiuterà a proseguire la tua formazione!", "." },
  ["9d6fe8bb04f342d9"] = { "Tra i colori, un sentiero.\n\nAttraversalo in un lampo di luce.\n\nDall'acqua, riemergi.", "." },
  ["9d7e67886611fdad"] = { "Non allontanarti troppo. Di sicuro ce ne sono altri là fuori.", "." },
  ["9d83db4e0ac26a41"] = { "Un applauso per {name}!", "." },
  ["9d849b0f30a299ea"] = { "Non temere! Ogni destino può essere svelato da chi conosce la via.", "." },
  ["9d8bc9d4aec93208"] = { "Insegnarti le arti dell'ingegneria gnomesca? Non se ne parla! Non da questo gnomo, almeno. Hai un fetore addosso, {name}. Forse parla la pietà, ma ti darò un consiglio.\n\nNel deserto di Tanaris troverai una capanna che appartiene a ⟦Narain Soothfancy=Narain Veravite⟧. In quella capanna c'è un libro magico noto per compiere prodigi. Trova quel libro e potresti ancora imparare la via degli gnomi.", "." },
  ["9d9ab5db1b0ed918"] = { "Il tuo spirito è debole, e i tuoi colpi lo sono ancora di più!", "." },
  ["9d9d3506eb9f39dd"] = { "Gli aggressori sono fuggiti! Forza e onore all'⟦Horde=Orda⟧!", "." },
  ["9da4aa503064c765"] = { "Dove sono i rinforzi da ⟦Stormwind=Roccavento⟧? Ci segnalano una forte attività dei ⟦Blackrock=Roccianera⟧ a est.", "." },
  ["9daa02c8c44d949f"] = { "Non sfuggirai al tuo destino, Onyxia. È stato profetizzato: una visione che riecheggia dalle grandi sale di Karazhan. Finisce qui...", "." },
  ["9dbeaff96334ea75"] = { "⟦Arathi Basin=Bacino d'Arathi⟧", "." },
  ["9dbfb9fae0862d65"] = { "Senza conoscere gli incantesimi necessari a unire le due parti, sire Linguatroce non ha potuto usare lo scettro. Ora però che la maledizione della corruzione di Linguatroce non grava più su di me, potrò aiutarti, se vorrai portarmi le due parti: sia la testa che l'asta dello scettro.", "." },
  ["9dc469d901560981"] = { "Sei <arrivato/arrivata> più lontano di molti, {name}. Rispetta gli elementi intorno a te e ti andrà molto meglio che alla maggior parte degli altri.", "." },
  ["9dc57ca0994ec809"] = { "Non c'è tempo da perdere, soldato. Devo tornare subito alla base! Coprimi!", "." },
  ["9dcdee345c09313e"] = { "Più liscia di un elfo, più forte di un orco! Non c'è da bere migliore in tutta ⟦Stormwind=Roccavento⟧!", "." },
  ["9dd21dfb0d72dfdc"] = { "Non voglio finire in pasto a un ogre! Ti prego, salvami!", "." },
  ["9dd277c3627eaa01"] = { "Salute, <mago/maga>. Vuoi approfondire la tua conoscenza del mondo della magia?", "." },
  ["9dd8a6482ef64000"] = { "Ho bisogno di addestramento", "." },
  ["9ddbaea817b296cb"] = { "Resta da vedere se sei <pronto/pronta>, giovane. Anche i druidi più saggi e anziani non sono mai davvero pronti quando giunge la loro prova suprema.\n\nHai udito le mie parole, e ora devi proseguire. Fa' tesoro di ciò che ti ho insegnato. Verrà un tempo in cui la tua forza sarà messa alla prova. Dovrai affrontare il nemico come farebbe l'orso: con la forza del corpo e con la forza del cuore. Impara dalla lotta, giovane. Va'... con la mia benedizione.", "." },
  ["9de15a0dc0c25009"] = { "L'ago è piccolo, ma il filo è forte, e i punti sono fini. Il nostro patto con Thrall e gli altri reggerà. L'⟦Horde=Orda⟧ non sarà cacciata da queste terre.", "." },
  ["9de4bd3675a744f7"] = { "Pieno zeppo di ratti! Dai una mano a un pirata, compare!", "." },
  ["9dea9bd83cdb549e"] = { "Mm, potrebbe essere quel ficcanaso di Shaw. Vedrò cosa riesco a scoprire. Ora vattene. Ti ricontatterò presto.", "." },
  ["9df7db8732faa182"] = { "Bene, soldati, riposo!", "." },
  ["9dfbde901c6b4144"] = { "%s si volta verso di te.", "." },
  ["9dfd60a6ba8d79b2"] = { "BORGOSCURO... HO FAME!!", "." },
})
